// Reads a tuning.presentation authoring file: the record, or every finding about it (DAT-024).
[[nodiscard]] inline Neuron::RecordResult<TuningPresentation> ReadTuningPresentation(const Neuron::JsonDocument& _document)
{
  Neuron::RecordReader reader(_document.file);
  TuningPresentation record;
  ReadFields(reader, reader.Record(_document.root, TUNING_PRESENTATION_SCHEMA_ID, TUNING_PRESENTATION_VERSION), record);
  if (reader.Failed())
  {
    return std::unexpected(reader.TakeDiagnostics());
  }
  return record;
}

