// Cooks a tuning.presentation record into the bytes of its entry (DAT-014): what the content build writes.
[[nodiscard]] inline std::vector<std::byte> CookTuningPresentation(const TuningPresentation& _record)
{
  Neuron::CookedWriter payload;
  CookFields(payload, _record);
  return Neuron::CookRecordEntry(TUNING_PRESENTATION_SCHEMA_ID, TUNING_PRESENTATION_VERSION, 1, payload.View());
}

// Reads a cooked tuning.presentation entry with no parsing: the record, or why the bytes are not one (DAT-050).
[[nodiscard]] inline std::expected<TuningPresentation, std::string> ReadCookedTuningPresentation(std::span<const std::byte> _entry)
{
  const auto payload = Neuron::OpenCookedRecord(_entry, TUNING_PRESENTATION_SCHEMA_ID, TUNING_PRESENTATION_VERSION, 1);
  if (!payload)
  {
    return std::unexpected(payload.error());
  }
  Neuron::CookedReader reader(*payload);
  TuningPresentation record;
  ReadCookedFields(reader, record);
  if (!reader.Finished())
  {
    return std::unexpected(std::string("the payload is not the size of a tuning.presentation record"));
  }
  return record;
}

